module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] state;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 0;
        end
        else begin
            case (state)
                0: state <= 1;
                1: state <= 2;
                2: state <= 0;
            endcase
        end
    end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
reg [1:0] current_state, next_state;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= 2'b00;
    end
    else begin
        current_state <= next_state;
    end
end

assign next_state = case (current_state)
    2'b00: 2'b01; 
    2'b01: 2'b10;
    2'b10: 2'b00;
    default: 2'b00;
endcase;

