module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [2:0] state, next_state;
    parameter IDLE = 3'b000, GREEN = 3'b001, YELLOW = 3'b010, RED = 3'b100;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always begin
        case (state)
            IDLE: next_state <= GREEN;
            GREEN: next_state <= YELLOW; 
            YELLOW: next_state <= RED;
            RED: next_state <= IDLE;
            default: next_state <= IDLE;
        endcase
    end

    assign light = state;
endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [2:0] light;
    reg [2:0] state, next_state;

    // State definitions: 0=stop, 1=go, 2=wait
    parameter stop = 3'b000;
    parameter go = 3'b001;
    parameter wait = 3'b010;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= stop;
        end else begin
            state <= next_state;
        end
    end

    always begin
        case (state)
            stop: begin
                light <= 3'b000;
                next_state <= go;
            end
            go: begin
                light <= 3'b001;
                next_state <= wait;
            end
            wait: begin
                light <= 3'b010;
                next_state <= stop;
            end
            default: begin
                light <= 3'b000;
                next_state <= go;
            end
        endcase
    end

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
// Add your code below. Ensure the code matches the provided circuit.
reg [1:0] state = 2'b00; // Based on the state machine design

// State machine mapping for the elevator controller
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: begin  // Idle
                if (up_request) state <= 2'b01;
                else if (down_request) state <= 2'b10;
            end
            2'b01: begin  // Moving up
                state <= 2'b11;
            end
            2'b10: begin  // Moving down
                state <= 2'b11;
            end
            2'b11: begin  // Moving to destination
                state <= 2'b00;
            end
        endcase
    end
end
endmodule

