module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    reg [1:0] state, next_state;
    reg [2:0] coin_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 0;
            coin_count <= 0;
        end else begin
            state <= next_state;
            if (state == 2'b00) begin
                if (coin_inserted) begin
                    coin_count <= coin_count + 1;
                    if (coin_count >= 3) begin
                        next_state <= 2'b01;
                        coin_count <= 0;
                    end
                end
            end else if (state == 2'b01) begin
                if (item_selected) begin
                    next_state <= 2'b10;
                end
            end else if (state == 2'b10) begin
                next_state <= 2'b00;
            end
        end
    end
endmodule

