module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;
     wire [33:1] carry;
     genvar i;

     for (i=1; i<=32; i=i+1) begin: ib
         assign carry[i] = carry[i-1] & A[i] & B[i] | carry[i-1] & (~A[i] | ~B[i]) & (~A[i] ^ B[i]) | (~A[i] & ~B[i]) & carry[i-1] | (A[i] ^ B[i]) & carry[i-1];
         assign S[i] = (A[i] ^ B[i]) ^ carry[i];
     end

     assign C32 = carry[33];
endmodule

