always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state_reg <= 3'b000;
    end
    else begin
        case (state_reg)
            3'b000: if (data_in) state_reg <= 3'b001;
            3'b001: if (data_in) state_reg <= 3'b010;
            3'b010: if (data_in) state_reg <= 3'b111;
            default: state_reg <= 3'b000;
        endcase
    end
end
assign sequence_detected = (state_reg == 3'b111);
endmodule

