        if (!rst_n) begin
            state <= 0;
        end
        else begin
            case (state)
                3: state <= 3;
                2: state <= (data_in == 1) ? 3 : 2;
                1: state <= (data_in == 1) ? 2 : 1;
                default: state <= (data_in == 1) ? 1 : 0;
            endcase
        end
    end
