module sequence_detector(
    input  clk, 
    input  rst_n,
    input  data_in, 
    output sequence_detected				
    );
    // State definitions for sequence detection
    reg [1:0] state, next_state;
    // Initial state (idle state)
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 2'b00; // Reset to initial state
        end else begin
            state <= next_state;
        end
    end;
    // State transition logic
    always @(*) begin
        case (state)
            2'b00: if (data_in == 1'b0) next_state = 2'b00; else next_state = 2'b01; // Next state on data_in=0
            2'b01: if (data_in == 1'b1) next_state = 2'b10; else next_state = 2'b00; // Next state on data_in=1
            2'b10: next_state = 2'b00; // Transition to idle state on subsequent input
            default: next_state = 2'b00; // Reset to initial state
        endcase
    end;
    // Output logic to indicate sequence detection
    assign sequence_detected = (state == 2'b10); // Sequence detected at state 2'b10
endmodule
